import test from'node:test';import assert from'node:assert/strict';import{create,simulate,basePrice}from'./engine.js';
test('actions change price and only then become information for the next forecast',()=>{const s=create(),r=simulate(s);for(let i=0;i<39;i++){const a=r.history[i],b=r.history[i+1];assert.ok(Math.abs(a.price-a.base-s.impact*a.mean)<1e-10);assert.ok(Math.abs(b.shared-a.shared-s.reaction*(a.price-a.shared))<1e-10);}});
test('removing price impact removes the self-induced outcome while keeping underlying demand',()=>{const s=create(),r=simulate({...s,impact:0});assert.ok(r.history.every(row=>row.price===basePrice(s.scenario,row.tick)));});
test('strong common feedback can oscillate more than slow feedback on the same underlying sequence',()=>{const s=create(),fast=simulate(s),slow=simulate({...s,reaction:.1});assert.deepEqual(fast.history.map(r=>r.base),slow.history.map(r=>r.base));assert.ok(fast.oscillation>slow.oscillation);for(const r of fast.history)assert.ok(r.actions.every(x=>x>=-1&&x<=1));assert.deepEqual(simulate(s),fast);});
